// One-off conversion script: TopoJSON (world-atlas land-110m) -> simplified GeoJSON rings
// bundled as a static asset. Not needed at runtime; run with `node scripts/convert-land.mjs`.
import { feature } from "topojson-client";
import { readFileSync, writeFileSync } from "fs";

const topo = JSON.parse(readFileSync("./scripts/land-110m.topo.json", "utf-8"));
const geo = feature(topo, topo.objects.land);

// Flatten to an array of polygon rings: number[][][] -> [ [ [lon,lat], ... ], ... ]
const rings = [];
for (const f of geo.features) {
  const geom = f.geometry;
  if (geom.type === "Polygon") {
    for (const ring of geom.coordinates) rings.push(ring);
  } else if (geom.type === "MultiPolygon") {
    for (const poly of geom.coordinates) {
      for (const ring of poly) rings.push(ring);
    }
  }
}

writeFileSync("./public/data/land.json", JSON.stringify(rings));
console.log(`Wrote ${rings.length} rings to public/data/land.json`);

