// Geo helpers for an equirectangular (plate carrée) projection, used by the
// canvas world map, trail, and predicted-path rendering.

export interface LatLon {
  lat: number;
  lon: number;
}

/** Shortest signed delta (in degrees) from `a` to `b`, wrapping at +/-180. */
export function shortestLonDelta(a: number, b: number): number {
  let d = (b - a) % 360;
  if (d > 180) d -= 360;
  if (d < -180) d += 360;
  return d;
}

/** Lerp latitude/longitude, taking the shortest path across the antimeridian. */
export function lerpLatLon(a: LatLon, b: LatLon, t: number): LatLon {
  const dLon = shortestLonDelta(a.lon, b.lon);
  let lon = a.lon + dLon * t;
  if (lon > 180) lon -= 360;
  if (lon < -180) lon += 360;
  return {
    lat: a.lat + (b.lat - a.lat) * t,
    lon,
  };
}

/** Equirectangular projection: lon/lat -> pixel x/y within a `width`x`height` canvas. */
export function project(
  { lat, lon }: LatLon,
  width: number,
  height: number
): { x: number; y: number } {
  const x = ((lon + 180) / 360) * width;
  const y = ((90 - lat) / 180) * height;
  return { x, y };
}

/**
 * Splits a sequence of lat/lon points into pixel-space segments, breaking a
 * segment wherever it would wrap around the antimeridian (so we don't draw a
 * spurious line all the way across the map).
 */
export function projectPath(
  points: LatLon[],
  width: number,
  height: number
): { x: number; y: number }[][] {
  const segments: { x: number; y: number }[][] = [];
  let current: { x: number; y: number }[] = [];

  for (let i = 0; i < points.length; i++) {
    const p = project(points[i], width, height);
    if (i > 0) {
      const prevLon = points[i - 1].lon;
      const lonDelta = Math.abs(points[i].lon - prevLon);
      if (lonDelta > 180) {
        // Antimeridian crossing: start a new segment.
        if (current.length > 1) segments.push(current);
        current = [];
      }
    }
    current.push(p);
  }
  if (current.length > 1) segments.push(current);
  return segments;
}

/** Exponential ease toward a target, frame-rate independent. Returns the new value. */
export function easeTowards(
  current: number,
  target: number,
  dtSeconds: number,
  rate: number
): number {
  const k = 1 - Math.exp(-rate * dtSeconds);
  return current + (target - current) * k;
}

/** Same as `easeTowards` but for lat/lon, taking the antimeridian shortcut. */
export function easeTowardsLatLon(
  current: LatLon,
  target: LatLon,
  dtSeconds: number,
  rate: number
): LatLon {
  const k = 1 - Math.exp(-rate * dtSeconds);
  const dLon = shortestLonDelta(current.lon, target.lon);
  let lon = current.lon + dLon * k;
  if (lon > 180) lon -= 360;
  if (lon < -180) lon += 360;
  return {
    lat: current.lat + (target.lat - current.lat) * k,
    lon,
  };
}

