// Client for the free, keyless wheretheiss.at API.
// https://wheretheiss.at/w/developer

const SATELLITE_ID = 25544; // ISS (ZARYA) NORAD catalog number
const BASE_URL = "https://api.wheretheiss.at/v1/satellites";

export interface IssPosition {
  lat: number;
  lon: number;
  altitudeKm: number;
  velocityKmh: number;
  visibility: "daylight" | "eclipsed" | string;
  timestamp: number; // unix seconds
}

interface RawPosition {
  latitude: number;
  longitude: number;
  altitude: number;
  velocity: number;
  visibility: string;
  timestamp: number;
}

function fromRaw(raw: RawPosition): IssPosition {
  return {
    lat: raw.latitude,
    lon: raw.longitude,
    altitudeKm: raw.altitude,
    velocityKmh: raw.velocity,
    visibility: raw.visibility,
    timestamp: raw.timestamp,
  };
}

/** Fetches the ISS's current position. */
export async function fetchCurrentPosition(signal?: AbortSignal): Promise<IssPosition> {
  const res = await fetch(`${BASE_URL}/${SATELLITE_ID}?units=kilometers`, { signal });
  if (!res.ok) throw new Error(`ISS position request failed: ${res.status}`);
  const raw: RawPosition = await res.json();
  return fromRaw(raw);
}

/**
 * Fetches predicted future positions along the ISS's orbit by asking the API
 * for a batch of future timestamps in one request. wheretheiss.at propagates
 * these from the satellite's current TLE (two-line element set) using SGP4,
 * so this is real orbit propagation rather than a geometric guess.
 */
export async function fetchPredictedPath(
  startUnixSeconds: number,
  stepSeconds: number,
  count: number,
  signal?: AbortSignal
): Promise<IssPosition[]> {
  const timestamps = Array.from({ length: count }, (_, i) => startUnixSeconds + i * stepSeconds);
  const res = await fetch(
    `${BASE_URL}/${SATELLITE_ID}/positions?timestamps=${timestamps.join(",")}&units=kilometers`,
    { signal }
  );
  if (!res.ok) throw new Error(`ISS prediction request failed: ${res.status}`);
  const raw: RawPosition[] = await res.json();
  return raw.map(fromRaw);
}

