"use client";

import { useEffect, useRef, useState } from "react";
import { fetchCurrentPosition, fetchPredictedPath, type IssPosition } from "./iss";

const POSITION_POLL_MS = 4000;
const PREDICTION_REFRESH_MS = 60_000;
const PREDICTION_STEP_SECONDS = 90;
const PREDICTION_COUNT = 30; // ~45 minutes ahead (roughly half an orbit)
const TRAIL_MAX_POINTS = 90; // ~6 minutes of history at the poll rate above

export interface IssTrackerState {
  current: IssPosition | null;
  trail: IssPosition[];
  predicted: IssPosition[];
  loading: boolean;
  error: string | null;
}

export function useIssTracker(): IssTrackerState {
  const [current, setCurrent] = useState<IssPosition | null>(null);
  const [trail, setTrail] = useState<IssPosition[]>([]);
  const [predicted, setPredicted] = useState<IssPosition[]>([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);
  const trailRef = useRef<IssPosition[]>([]);

  useEffect(() => {
    let cancelled = false;
    const controller = new AbortController();

    async function pollPosition() {
      try {
        const pos = await fetchCurrentPosition(controller.signal);
        if (cancelled) return;
        setCurrent(pos);
        setError(null);
        setLoading(false);

        const last = trailRef.current[trailRef.current.length - 1];
        if (!last || last.timestamp !== pos.timestamp) {
          const next = [...trailRef.current, pos].slice(-TRAIL_MAX_POINTS);
          trailRef.current = next;
          setTrail(next);
        }
      } catch (err) {
        if (cancelled || controller.signal.aborted) return;
        setError(err instanceof Error ? err.message : "Failed to fetch ISS position");
        setLoading(false);
      }
    }

    async function pollPrediction() {
      try {
        const nowSeconds = Math.floor(Date.now() / 1000);
        const path = await fetchPredictedPath(
          nowSeconds,
          PREDICTION_STEP_SECONDS,
          PREDICTION_COUNT,
          controller.signal
        );
        if (cancelled) return;
        setPredicted(path);
      } catch {
        // Predicted path is a nice-to-have; silently retry on the next tick
        // rather than surfacing an error for the whole dashboard.
      }
    }

    pollPosition();
    pollPrediction();
    const positionTimer = setInterval(pollPosition, POSITION_POLL_MS);
    const predictionTimer = setInterval(pollPrediction, PREDICTION_REFRESH_MS);

    return () => {
      cancelled = true;
      controller.abort();
      clearInterval(positionTimer);
      clearInterval(predictionTimer);
    };
  }, []);

  return { current, trail, predicted, loading, error };
}

