"use client";

import { useEffect, useRef } from "react";
import type { IssPosition } from "@/lib/iss";
import { easeTowardsLatLon, project, projectPath, type LatLon } from "@/lib/geo";

const OCEAN_TOP = "#060a16";
const OCEAN_BOTTOM = "#0a1226";
const LAND_FILL = "#132038";
const LAND_STROKE = "#24375c";
const GRID_LINE = "rgba(90, 120, 170, 0.08)";
const TRAIL_COLOR = [56, 229, 193] as const; // teal
const PREDICTED_COLOR = "rgba(250, 190, 90, 0.85)"; // amber
const EASE_RATE = 1.4; // higher = snappier chase toward the latest fetched fix

interface Props {
  current: IssPosition | null;
  trail: IssPosition[];
  predicted: IssPosition[];
}

export default function WorldMap({ current, trail, predicted }: Props) {
  const canvasRef = useRef<HTMLCanvasElement | null>(null);
  const containerRef = useRef<HTMLDivElement | null>(null);
  const landRef = useRef<LatLon[][] | null>(null);

  // Mutable animation state kept outside React so the rAF loop never fights re-renders.
  const displayedRef = useRef<LatLon | null>(null);
  const targetRef = useRef<LatLon | null>(null);
  const trailRef = useRef<IssPosition[]>([]);
  const predictedRef = useRef<IssPosition[]>([]);
  const sizeRef = useRef({ width: 0, height: 0, dpr: 1 });

  useEffect(() => {
    let cancelled = false;
    fetch("/data/land.json")
      .then((res) => res.json())
      .then((rings: [number, number][][]) => {
        if (cancelled) return;
        landRef.current = rings.map((ring) => ring.map(([lon, lat]) => ({ lat, lon })));
      })
      .catch(() => {
        landRef.current = [];
      });
    return () => {
      cancelled = true;
    };
  }, []);

  useEffect(() => {
    if (current) {
      targetRef.current = { lat: current.lat, lon: current.lon };
      if (!displayedRef.current) {
        displayedRef.current = { lat: current.lat, lon: current.lon };
      }
    }
  }, [current]);

  useEffect(() => {
    trailRef.current = trail;
  }, [trail]);

  useEffect(() => {
    predictedRef.current = predicted;
  }, [predicted]);

  useEffect(() => {
    const canvas = canvasRef.current;
    const container = containerRef.current;
    if (!canvas || !container) return;
    const ctx = canvas.getContext("2d");
    if (!ctx) return;

    function resize() {
      const rect = container!.getBoundingClientRect();
      const dpr = Math.min(window.devicePixelRatio || 1, 2);
      sizeRef.current = { width: rect.width, height: rect.height, dpr };
      canvas!.width = Math.round(rect.width * dpr);
      canvas!.height = Math.round(rect.height * dpr);
      canvas!.style.width = `${rect.width}px`;
      canvas!.style.height = `${rect.height}px`;
    }
    resize();
    const ro = new ResizeObserver(resize);
    ro.observe(container);

    let rafId = 0;
    let lastTime = performance.now();

    function drawGrid(width: number, height: number) {
      ctx!.strokeStyle = GRID_LINE;
      ctx!.lineWidth = 1;
      for (let lon = -180; lon <= 180; lon += 30) {
        const x = ((lon + 180) / 360) * width;
        ctx!.beginPath();
        ctx!.moveTo(x, 0);
        ctx!.lineTo(x, height);
        ctx!.stroke();
      }
      for (let lat = -60; lat <= 60; lat += 30) {
        const y = ((90 - lat) / 180) * height;
        ctx!.beginPath();
        ctx!.moveTo(0, y);
        ctx!.lineTo(width, y);
        ctx!.stroke();
      }
      // Equator, slightly brighter
      ctx!.strokeStyle = "rgba(90, 120, 170, 0.16)";
      const yEq = height / 2;
      ctx!.beginPath();
      ctx!.moveTo(0, yEq);
      ctx!.lineTo(width, yEq);
      ctx!.stroke();
    }

    function drawLand(width: number, height: number) {
      const rings = landRef.current;
      if (!rings) return;
      ctx!.fillStyle = LAND_FILL;
      ctx!.strokeStyle = LAND_STROKE;
      ctx!.lineWidth = 1;
      for (const ring of rings) {
        if (ring.length < 3) continue;
        // Skip drawing a single path across the antimeridian by splitting ring into segments.
        const segments = projectPath(ring, width, height);
        for (const seg of segments) {
          if (seg.length < 3) continue;
          ctx!.beginPath();
          ctx!.moveTo(seg[0].x, seg[0].y);
          for (let i = 1; i < seg.length; i++) ctx!.lineTo(seg[i].x, seg[i].y);
          ctx!.closePath();
          ctx!.fill();
          ctx!.stroke();
        }
      }
    }

    function drawTrail(width: number, height: number, head: LatLon) {
      const pts = trailRef.current;
      if (pts.length === 0) return;
      const full: LatLon[] = [...pts.map((p) => ({ lat: p.lat, lon: p.lon })), head];
      const n = full.length;
      for (let i = 1; i < n; i++) {
        const a = full[i - 1];
        const b = full[i];
        if (Math.abs(a.lon - b.lon) > 180) continue; // antimeridian gap
        const pa = project(a, width, height);
        const pb = project(b, width, height);
        const alpha = (i / n) * 0.8;
        const [r, g, bch] = TRAIL_COLOR;
        ctx!.strokeStyle = `rgba(${r}, ${g}, ${bch}, ${alpha})`;
        ctx!.lineWidth = 1.5 + (i / n) * 1.5;
        ctx!.beginPath();
        ctx!.moveTo(pa.x, pa.y);
        ctx!.lineTo(pb.x, pb.y);
        ctx!.stroke();
      }
    }

    function drawPredicted(width: number, height: number, head: LatLon) {
      const pts = predictedRef.current;
      if (pts.length === 0) return;
      const full: LatLon[] = [head, ...pts.map((p) => ({ lat: p.lat, lon: p.lon }))];
      const segments = projectPath(full, width, height);
      ctx!.strokeStyle = PREDICTED_COLOR;
      ctx!.lineWidth = 1.75;
      ctx!.setLineDash([2, 7]);
      for (const seg of segments) {
        if (seg.length < 2) continue;
        ctx!.beginPath();
        ctx!.moveTo(seg[0].x, seg[0].y);
        for (let i = 1; i < seg.length; i++) ctx!.lineTo(seg[i].x, seg[i].y);
        ctx!.stroke();
      }
      ctx!.setLineDash([]);
    }

    function drawMarker(width: number, height: number, pos: LatLon, t: number) {
      const { x, y } = project(pos, width, height);
      const pulse = 0.5 + 0.5 * Math.sin(t / 420);

      const outerRadius = 20 + pulse * 6;
      const glow = ctx!.createRadialGradient(x, y, 0, x, y, outerRadius);
      glow.addColorStop(0, "rgba(120, 245, 220, 0.55)");
      glow.addColorStop(0.4, "rgba(80, 220, 200, 0.22)");
      glow.addColorStop(1, "rgba(80, 220, 200, 0)");
      ctx!.fillStyle = glow;
      ctx!.beginPath();
      ctx!.arc(x, y, outerRadius, 0, Math.PI * 2);
      ctx!.fill();

      ctx!.beginPath();
      ctx!.arc(x, y, 5, 0, Math.PI * 2);
      ctx!.fillStyle = "#eafff6";
      ctx!.fill();
      ctx!.lineWidth = 1.5;
      ctx!.strokeStyle = "rgba(80, 220, 200, 0.9)";
      ctx!.stroke();
    }

    function frame(now: number) {
      const dt = Math.min((now - lastTime) / 1000, 0.25);
      lastTime = now;
      const { width, height } = sizeRef.current;
      const dpr = sizeRef.current.dpr;

      ctx!.save();
      ctx!.scale(dpr, dpr);

      const bg = ctx!.createLinearGradient(0, 0, 0, height);
      bg.addColorStop(0, OCEAN_TOP);
      bg.addColorStop(1, OCEAN_BOTTOM);
      ctx!.fillStyle = bg;
      ctx!.fillRect(0, 0, width, height);

      drawGrid(width, height);
      drawLand(width, height);

      if (targetRef.current) {
        if (!displayedRef.current) displayedRef.current = { ...targetRef.current };
        displayedRef.current = easeTowardsLatLon(
          displayedRef.current,
          targetRef.current,
          dt,
          EASE_RATE
        );
        drawPredicted(width, height, displayedRef.current);
        drawTrail(width, height, displayedRef.current);
        drawMarker(width, height, displayedRef.current, now);
      }

      ctx!.restore();
      rafId = requestAnimationFrame(frame);
    }

    rafId = requestAnimationFrame(frame);

    return () => {
      ro.disconnect();
      cancelAnimationFrame(rafId);
    };
  }, []);

  return (
    <div ref={containerRef} className="map-shell">
      <canvas ref={canvasRef} />
      <div className="map-legend">
        <span className="legend-item">
          <i className="dot dot-live" /> live track
        </span>
        <span className="legend-item">
          <i className="dot dot-predicted" /> predicted orbit
        </span>
      </div>
    </div>
  );
}

