      // Equator, slightly brighter
      ctx!.strokeStyle = "rgba(90, 120, 170, 0.16)";
      const yEq = height / 2;
      ctx!.beginPath();
      ctx!.moveTo(0, yEq);
      ctx!.lineTo(width, yEq);
      ctx!.stroke();
    }

    function drawLand(width: number, height: number) {
      const rings = landRef.current;
      if (!rings) return;
      ctx!.fillStyle = LAND_FILL;
      ctx!.strokeStyle = LAND_STROKE;
      ctx!.lineWidth = 1;
      for (const ring of rings) {
        if (ring.length < 3) continue;
        // Skip drawing a single path across the antimeridian by splitting ring into segments.
        const segments = projectPath(ring, width, height);
        for (const seg of segments) {
          if (seg.length < 3) continue;
          ctx!.beginPath();
          ctx!.moveTo(seg[0].x, seg[0].y);
          for (let i = 1; i < seg.length; i++) ctx!.lineTo(seg[i].x, seg[i].y);
          ctx!.closePath();
          ctx!.fill();
          ctx!.stroke();
        }
      }
    }

    function drawTrail(width: number, height: number, head: LatLon) {
      const pts = trailRef.current;
      if (pts.length === 0) return;
      const full: LatLon[] = [...pts.map((p) => ({ lat: p.lat, lon: p.lon })), head];
      const n = full.length;
      for (let i = 1; i < n; i++) {
        const a = full[i - 1];
        const b = full[i];
        if (Math.abs(a.lon - b.lon) > 180) continue; // antimeridian gap
        const pa = project(a, width, height);
        const pb = project(b, width, height);
        const alpha = (i / n) * 0.8;
        const [r, g, bch] = TRAIL_COLOR;
        ctx!.strokeStyle = `rgba(${r}, ${g}, ${bch}, ${alpha})`;
        ctx!.lineWidth = 1.5 + (i / n) * 1.5;
        ctx!.beginPath();
        ctx!.moveTo(pa.x, pa.y);
        ctx!.lineTo(pb.x, pb.y);
        ctx!.stroke();
      }
    }

    function drawPredicted(width: number, height: number, head: LatLon) {
      const pts = predictedRef.current;
      if (pts.length === 0) return;
      const full: LatLon[] = [head, ...pts.map((p) => ({ lat: p.lat, lon: p.lon }))];
      const segments = projectPath(full, width, height);
      ctx!.strokeStyle = PREDICTED_COLOR;
      ctx!.lineWidth = 1.75;
      ctx!.setLineDash([2, 7]);
      for (const seg of segments) {
        if (seg.length < 2) continue;
        ctx!.beginPath();
        ctx!.moveTo(seg[0].x, seg[0].y);
        for (let i = 1; i < seg.length; i++) ctx!.lineTo(seg[i].x, seg[i].y);
        ctx!.stroke();
      }
      ctx!.setLineDash([]);
    }

    function drawMarker(width: number, height: number, pos: LatLon, t: number) {
      const { x, y } = project(pos, width, height);
      const pulse = 0.5 + 0.5 * Math.sin(t / 420);

      const outerRadius = 20 + pulse * 6;
      const glow = ctx!.createRadialGradient(x, y, 0, x, y, outerRadius);
      glow.addColorStop(0, "rgba(120, 245, 220, 0.55)");
      glow.addColorStop(0.4, "rgba(80, 220, 200, 0.22)");
      glow.addColorStop(1, "rgba(80, 220, 200, 0)");
      ctx!.fillStyle = glow;
      ctx!.beginPath();
      ctx!.arc(x, y, outerRadius, 0, Math.PI * 2);
      ctx!.fill();

      ctx!.beginPath();
      ctx!.arc(x, y, 5, 0, Math.PI * 2);
      ctx!.fillStyle = "#eafff6";
      ctx!.fill();
      ctx!.lineWidth = 1.5;
      ctx!.strokeStyle = "rgba(80, 220, 200, 0.9)";
      ctx!.stroke();
    }

    function frame(now: number) {
      const dt = Math.min((now - lastTime) / 1000, 0.25);
      lastTime = now;
      const { width, height } = sizeRef.current;
      const dpr = sizeRef.current.dpr;

      ctx!.save();
      ctx!.scale(dpr, dpr);

      const bg = ctx!.createLinearGradient(0, 0, 0, height);
      bg.addColorStop(0, OCEAN_TOP);
      bg.addColorStop(1, OCEAN_BOTTOM);
      ctx!.fillStyle = bg;
      ctx!.fillRect(0, 0, width, height);

      drawGrid(width, height);
      drawLand(width, height);

      if (targetRef.current) {
        if (!displayedRef.current) displayedRef.current = { ...targetRef.current };
        displayedRef.current = easeTowardsLatLon(
          displayedRef.current,
          targetRef.current,
          dt,
          EASE_RATE
        );
        drawPredicted(width, height, displayedRef.current);
        drawTrail(width, height, displayedRef.current);
        drawMarker(width, height, displayedRef.current, now);
      }

      ctx!.restore();
      rafId = requestAnimationFrame(frame);
    }

    rafId = requestAnimationFrame(frame);

    return () => {
      ro.disconnect();
      cancelAnimationFrame(rafId);
    };
  }, []);

  return (
    <div ref={containerRef} className="map-shell">
      <canvas ref={canvasRef} />
      <div className="map-legend">
        <span className="legend-item">
          <i className="dot dot-live" /> live track
        </span>
        <span className="legend-item">
          <i className="dot dot-predicted" /> predicted orbit
        </span>
      </div>
    </div>
  );
}

input.content:
"use client";

import type { IssPosition } from "@/lib/iss";

function formatCoord(value: number, posLabel: string, negLabel: string): string {
  const hemisphere = value >= 0 ? posLabel : negLabel;
  return `${Math.abs(value).toFixed(4)}° ${hemisphere}`;
}

function StatRow({ label, value, unit }: { label: string; value: string; unit?: string }) {
  return (
    <div className="stat-row">
      <span className="stat-label">{label}</span>
      <span className="stat-value">
        {value}
        {unit ? <span className="stat-unit">{unit}</span> : null}
      </span>
    </div>
  );
}

export default function StatsPanel({
  current,
  loading,
  error,
}: {
  current: IssPosition | null;
  loading: boolean;
  error: string | null;
}) {
  if (loading && !current) {
    return (
      <div className="panel stats-panel">
        <h2>Telemetry</h2>
        <p className="muted">Acquiring signal…</p>
      </div>
    );
  }

  if (error && !current) {
    return (
      <div className="panel stats-panel">
        <h2>Telemetry</h2>
        <p className="error">{error}</p>
      </div>
    );
  }

  if (!current) return null;

  const updated = new Date(current.timestamp * 1000);

  return (
    <div className="panel stats-panel">
      <h2>Telemetry</h2>
      <StatRow label="Latitude" value={formatCoord(current.lat, "N", "S")} />
      <StatRow label="Longitude" value={formatCoord(current.lon, "E", "W")} />
      <StatRow label="Altitude" value={current.altitudeKm.toFixed(1)} unit="km" />
      <StatRow label="Velocity" value={current.velocityKmh.toFixed(0)} unit="km/h" />
      <StatRow
        label="Visibility"
        value={current.visibility === "daylight" ? "Daylight" : "Eclipsed"}
      />
      <div className="stat-divider" />
      <StatRow
        label="Last fix"
        value={updated.toLocaleTimeString(undefined, {
          hour: "2-digit",
          minute: "2-digit",
          second: "2-digit",
        })}
      />
      {error ? <p className="error subtle">Reconnecting: {error}</p> : null}
    </div>
  );
}

