"use client";

import { useEffect, useState } from "react";

export default function Header() {
  const [now, setNow] = useState<Date | null>(null);

  useEffect(() => {
    setNow(new Date());
    const id = setInterval(() => setNow(new Date()), 1000);
    return () => clearInterval(id);
  }, []);

  return (
    <header className="app-header">
      <div className="brand">
        <span className="brand-mark" aria-hidden />
        <div>
          <h1>Orbitwatch</h1>
          <p className="tagline">Live ISS position &amp; orbit tracker</p>
        </div>
      </div>
      <div className="utc-clock" suppressHydrationWarning>
        {now
          ? now.toLocaleTimeString(undefined, {
              hour: "2-digit",
              minute: "2-digit",
              second: "2-digit",
              timeZone: "UTC",
              timeZoneName: "short",
            })
          : "—"}
      </div>
    </header>
  );
}

