input.content:
:root {
  --bg: #05070d;
  --panel-bg: #0d1222;
  --panel-border: #1c2740;
  --text: #e7edf7;
  --text-muted: #8392ad;
  --accent: #52e3c6;
  --accent-amber: #f6b955;
  --danger: #ff6b6b;
}

* {
  box-sizing: border-box;
}

html,
body {
  margin: 0;
  padding: 0;
  background: var(--bg);
  color: var(--text);
  font-family: -apple-system, BlinkMacSystemFont, "Segoe UI", Inter, Roboto, Helvetica, Arial,
    sans-serif;
}

a {
  color: var(--accent);
}

.page {
  min-height: 100vh;
  display: flex;
  flex-direction: column;
}

.app-header {
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: 1.1rem 1.5rem;
  border-bottom: 1px solid var(--panel-border);
  background: linear-gradient(180deg, rgba(13, 18, 34, 0.9), rgba(13, 18, 34, 0.4));
}

.brand {
  display: flex;
  align-items: center;
  gap: 0.75rem;
}

.brand-mark {
  width: 14px;
  height: 14px;
  border-radius: 50%;
  background: radial-gradient(circle at 35% 35%, #eafff6, var(--accent) 60%, #0d3f36 100%);
  box-shadow: 0 0 14px rgba(82, 227, 198, 0.7);
  flex-shrink: 0;
}

.brand h1 {
  margin: 0;
  font-size: 1.25rem;
  letter-spacing: 0.04em;
}

.tagline {
  margin: 0.1rem 0 0;
  font-size: 0.8rem;
  color: var(--text-muted);
}

.utc-clock {
  font-family: "SF Mono", ui-monospace, Menlo, Consolas, monospace;
  font-size: 0.95rem;
  color: var(--text-muted);
  letter-spacing: 0.03em;
}

.layout {
  flex: 1;
  display: grid;
  grid-template-columns: minmax(0, 1fr) 280px;
  gap: 1rem;
  padding: 1rem 1.5rem;
}

.map-section {
  min-height: 420px;
  border-radius: 14px;
  overflow: hidden;
  border: 1px solid var(--panel-border);
}

.map-shell {
  position: relative;
  width: 100%;
  height: 100%;
  min-height: 420px;
}

.map-shell canvas {
  display: block;
  width: 100%;
  height: 100%;
}

.map-legend {
  position: absolute;
  bottom: 0.9rem;
  left: 0.9rem;
  display: flex;
  gap: 1rem;
  padding: 0.5rem 0.8rem;
  background: rgba(5, 7, 13, 0.6);
  border: 1px solid var(--panel-border);
  border-radius: 8px;
  font-size: 0.75rem;
  color: var(--text-muted);
  backdrop-filter: blur(4px);
}

.legend-item {
  display: flex;
  align-items: center;
  gap: 0.4rem;
}

.dot {
  width: 8px;
  height: 8px;
  border-radius: 50%;
  display: inline-block;
}

.dot-live {
  background: var(--accent);
  box-shadow: 0 0 6px rgba(82, 227, 198, 0.8);
}

.dot-predicted {
  background: var(--accent-amber);
  box-shadow: 0 0 6px rgba(246, 185, 85, 0.8);
}

.sidebar {
  display: flex;
  flex-direction: column;
  gap: 1rem;
}

.panel {
  background: var(--panel-bg);
  border: 1px solid var(--panel-border);
  border-radius: 14px;
  padding: 1.1rem 1.2rem;
}

.panel h2 {
  margin: 0 0 0.75rem;
  font-size: 0.8rem;
  text-transform: uppercase;
  letter-spacing: 0.08em;
  color: var(--text-muted);
}

.stat-row {
  display: flex;
  align-items: baseline;
  justify-content: space-between;
  padding: 0.35rem 0;
  font-size: 0.92rem;
}

.stat-label {
  color: var(--text-muted);
}

.stat-value {
  font-family: "SF Mono", ui-monospace, Menlo, Consolas, monospace;
  font-weight: 600;
}

.stat-unit {
  margin-left: 0.25rem;
  color: var(--text-muted);
  font-weight: 400;
  font-size: 0.8em;
}

.stat-divider {
  height: 1px;
  background: var(--panel-border);
  margin: 0.5rem 0;
}

.muted {
  color: var(--text-muted);
  font-size: 0.9rem;
}

.error {
  color: var(--danger);
  font-size: 0.9rem;
}

.error.subtle {
  font-size: 0.75rem;
  opacity: 0.8;
}

.app-footer {
  text-align: center;
  padding: 0.9rem 1rem 1.2rem;
  font-size: 0.75rem;
  color: var(--text-muted);
}

@media (max-width: 860px) {
  .layout {
    grid-template-columns: 1fr;
  }

  .map-section {
    min-height: 340px;
  }
}

