  display: flex;
  align-items: center;
  gap: 0.4rem;
}

.dot {
  width: 8px;
  height: 8px;
  border-radius: 50%;
  display: inline-block;
}

.dot-live {
  background: var(--accent);
  box-shadow: 0 0 6px rgba(82, 227, 198, 0.8);
}

.dot-predicted {
  background: var(--accent-amber);
  box-shadow: 0 0 6px rgba(246, 185, 85, 0.8);
}

.sidebar {
  display: flex;
  flex-direction: column;
  gap: 1rem;
}

.panel {
  background: var(--panel-bg);
  border: 1px solid var(--panel-border);
  border-radius: 14px;
  padding: 1.1rem 1.2rem;
}

.panel h2 {
  margin: 0 0 0.75rem;
  font-size: 0.8rem;
  text-transform: uppercase;
  letter-spacing: 0.08em;
  color: var(--text-muted);
}

.stat-row {
  display: flex;
  align-items: baseline;
  justify-content: space-between;
  padding: 0.35rem 0;
  font-size: 0.92rem;
}

.stat-label {
  color: var(--text-muted);
}

.stat-value {
  font-family: "SF Mono", ui-monospace, Menlo, Consolas, monospace;
  font-weight: 600;
}

.stat-unit {
  margin-left: 0.25rem;
  color: var(--text-muted);
  font-weight: 400;
  font-size: 0.8em;
}

.stat-divider {
  height: 1px;
  background: var(--panel-border);
  margin: 0.5rem 0;
}

.muted {
  color: var(--text-muted);
  font-size: 0.9rem;
}

.error {
  color: var(--danger);
  font-size: 0.9rem;
}

.error.subtle {
  font-size: 0.75rem;
  opacity: 0.8;
}

.app-footer {
  text-align: center;
  padding: 0.9rem 1rem 1.2rem;
  font-size: 0.75rem;
  color: var(--text-muted);
}

@media (max-width: 860px) {
  .layout {
    grid-template-columns: 1fr;
  }

  .map-section {
    min-height: 340px;
  }
}

