:root {
  --bg: #05070d;
  --panel-bg: #0d1222;
  --panel-border: #1c2740;
  --text: #e7edf7;
  --text-muted: #8392ad;
  --accent: #52e3c6;
  --accent-amber: #f6b955;
  --danger: #ff6b6b;
}

* {
  box-sizing: border-box;
}

html,
body {
  margin: 0;
  padding: 0;
  background: var(--bg);
  color: var(--text);
  font-family: -apple-system, BlinkMacSystemFont, "Segoe UI", Inter, Roboto, Helvetica, Arial,
    sans-serif;
}

a {
  color: var(--accent);
}

.page {
  min-height: 100vh;
  display: flex;
  flex-direction: column;
}

.app-header {
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: 1.1rem 1.5rem;
  border-bottom: 1px solid var(--panel-border);
  background: linear-gradient(180deg, rgba(13, 18, 34, 0.9), rgba(13, 18, 34, 0.4));
}

.brand {
  display: flex;
  align-items: center;
  gap: 0.75rem;
}

.brand-mark {
  width: 14px;
  height: 14px;
  border-radius: 50%;
  background: radial-gradient(circle at 35% 35%, #eafff6, var(--accent) 60%, #0d3f36 100%);
  box-shadow: 0 0 14px rgba(82, 227, 198, 0.7);
  flex-shrink: 0;
}

.brand h1 {
  margin: 0;
  font-size: 1.25rem;
  letter-spacing: 0.04em;
}

.tagline {
  margin: 0.1rem 0 0;
  font-size: 0.8rem;
  color: var(--text-muted);
}

.utc-clock {
  font-family: "SF Mono", ui-monospace, Menlo, Consolas, monospace;
  font-size: 0.95rem;
  color: var(--text-muted);
  letter-spacing: 0.03em;
}

.layout {
  flex: 1;
  display: grid;
  grid-template-columns: minmax(0, 1fr) 280px;
  gap: 1rem;
  padding: 1rem 1.5rem;
}

.map-section {
  min-height: 420px;
  border-radius: 14px;
  overflow: hidden;
  border: 1px solid var(--panel-border);
}

.map-shell {
