import { chromium } from "playwright";

const browser = await chromium.launch({ args: ["--no-sandbox"] });
const page = await browser.newPage({ viewport: { width: 1400, height: 900 } });
const errors = [];
page.on("console", (msg) => {
  if (msg.type() === "error") errors.push(msg.text());
});
page.on("pageerror", (err) => errors.push(String(err)));

await page.goto("http://localhost:3000", { waitUntil: "networkidle" });
await page.waitForSelector("canvas");
await page.waitForTimeout(3500); // let a couple of animation frames / fetches settle
await page.screenshot({ path: "/tmp/claude-1000/-Users-user-Code-tape-iss/c7539960-8887-448b-84d3-adbda7a04120/scratchpad/pw/screenshot1.png" });

await page.setViewportSize({ width: 390, height: 844 });
await page.waitForTimeout(500);
await page.screenshot({ path: "/tmp/claude-1000/-Users-user-Code-tape-iss/c7539960-8887-448b-84d3-adbda7a04120/scratchpad/pw/screenshot-mobile.png" });

console.log("CONSOLE_ERRORS:", JSON.stringify(errors));
await browser.close();

